// The User, Scheme, and EducationLevel types are auto-generated by Prisma.
// If you see an error here, run `npx prisma generate` in your terminal.
import { User, Scheme, EducationLevel } from "@prisma/client";

// A helper to parse income ranges like "₹1,00,000 – ₹3,00,000 per year"
function isIncomeInRange(userIncome: number, range: string): boolean {
  const numbers = range.match(/\d[\d,]*\d/g);
  if (!numbers || numbers.length === 0) return false;

  const cleanAndParse = (s: string) => parseInt(s.replace(/,/g, ""), 10);

  if (range.toLowerCase().includes("below")) {
    return userIncome < cleanAndParse(numbers[0]);
  }

  if (range.toLowerCase().includes("above")) {
    return userIncome > cleanAndParse(numbers[0]);
  }

  if (numbers.length === 2) {
    const min = cleanAndParse(numbers[0]);
    const max = cleanAndParse(numbers[1]);
    return userIncome >= min && userIncome <= max;
  }

  return false;
}

// This maps your EducationLevel enum to a numeric value for comparison
const educationHierarchy: Record<EducationLevel, number> = {
  MATRICULATION: 1,
  HIGHER_SECONDARY: 2,
  DIPLOMA: 2, // Often considered equivalent to or just above HS
  GRADUATION: 3,
  POST_GRADUATION: 4,
  PHD: 5,
};

export const eligibilityEngine = {
  isEligible(user: User, scheme: Scheme): boolean {
    try {
      // 1. Check User Data completeness
      if (!user.income || !user.education || !user.state || !user.district) {
        return false; // User profile is incomplete for matching
      }

      // 2. Check Location
      if (
        scheme.state.toLowerCase() !== user.state.toLowerCase() ||
        scheme.district.toLowerCase() !== user.district.toLowerCase()
      ) {
        return false; // Not in the right location
      }

      // 3. Check Base Criteria from the scheme's JSON field
      const criteria = scheme.baseCriteria as {
        incomeLevel?: string;
        minEducation?: EducationLevel; // Expecting an enum value like "GRADUATION"
      };

      // Check income level
      if (criteria.incomeLevel) {
        if (!isIncomeInRange(user.income, criteria.incomeLevel)) {
          return false; // Income does not match
        }
      }

      // Check education level using the enum hierarchy
      if (criteria.minEducation) {
        const requiredLevel = educationHierarchy[criteria.minEducation];
        const userLevel = educationHierarchy[user.education];

        // If either level is not in our hierarchy, or user's level is too low
        if (userLevel === undefined || requiredLevel === undefined || userLevel < requiredLevel) {
          return false; // Education level is too low
        }
      }

      // If all checks pass, the user is eligible
      return true;
    } catch (error) {
      console.error(`Error checking eligibility for user ${user.id} and scheme ${scheme.id}:`, error);
      return false;
    }
  },
};